/// <summary>
/// CB624_TMSEngineSOCreation
/// Class to proceede with the creation process for TMS engine
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::SalesOrderCreation)]
internal final class METTMSEngineSalesOrderProccess_Creation extends METTMSEngineOrderProccess
{    
    METSalesTable metSalesTable;

}

Method.Source:
/// <summary>
///
/// </summary>
/// <param name = "_sourceRecord"></param>
protected void init(METTMSSourceRecordHeaderMap _sourceRecord)
{
    super(_sourceRecord);
    metSalesTable = headerContract.getExtensionTable();
}

    /// <summary>
    ///
    /// </summary>
    /// <returns></returns>
    protected METRouteIdentifier getRouteIdentifier()
    {
        METRouteIdentifier ret = metSalesTable.OriginalRouteIdentifier;

        return ret;
    }

    /// <summary>
    ///
    /// </summary>
    /// <returns></returns>
    public METStagingLaneId getStagingLaneId()
    {
        METStagingLaneId ret = metSalesTable.StagingLaneId;

        return ret;
    }

    /// <summary>
    ///
    /// </summary>
    /// <returns></returns>
    protected METRouteStopIdentifier getRouteStopIdentifier()
    {
        METRouteStopIdentifier ret = metSalesTable.OriginalRouteStopIdentifier;

        return ret;
    }

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return strFmt("@MET:TMSEngineSalesOrderProcessCreation", headerContract.parmSourceRecord().OrderId);
}

    /// <summary>
    /// Gets the execution mode of the process class
    /// </summary>
    /// <returns><c>METTMSEngineExecutionMode</c></returns>
    public METTMSEngineExecutionMode getExecutionMode()
    {
        METTMSEngineExecutionMode ret = METTMSEngineExecutionMode::SalesOrderCreation;

        return ret;
    }
